    "elements": [
      {
        "type": "obj",
        "desc": "Single magnolia blossom in full bloom, anchored slightly above center as the focal subject occupying roughly the upper-middle third of the frame. Six to eight cream-colored petals fanning outward, subtle copper-ochre shading at petal bases and along the inner cup. Exposed stamen cluster at the center with fine copper filaments and pale pollen-tipped anthers. Fine ink contours define petal edges; watercolor washes model gentle tonal depth."
      },
      {
        "type": "obj",
        "desc": "Glossy magnolia leaf fanning diagonally to the lower-left of the blossom. Deep forest green with a waxy sheen, prominent central vein and finely parallel lateral veins etched in darker green ink. Slightly curled edge reveals the paler underside along one margin."
      },
      {
        "type": "obj",
        "desc": "Glossy magnolia leaf fanning diagonally to the lower-right, mirroring its companion leaf to balance the frame. Deep forest green with waxy sheen, central vein and parallel lateral veins in darker green ink, smooth oval form with a pointed tip."
      },
      {
        "type": "obj",
        "desc": "Slender stem connecting the blossom above to the leaves below, running vertically through the center. Warm copper-brown with faint lenticel speckling along its length, fine ink contour defining its edges."
      },
      {
        "type": "obj",
        "desc": "One unopened magnolia bud tucked behind the main blossom at upper right, tight ovoid form wrapped in overlapping cream-and-copper scales. Copper-ochre shading along the scale edges, pale cream centers, fine ink linework defining each overlapping scale."
      }
    ]
  }
}

